        wire(query,"controlledFileMapper",files,"signatureMapper",sqlMapper(DccControlledFileSignatureMapper.class),"signatureBindingService",ReflectionTestUtils.getField(nativeVerifier,"signatureBindingService"),"detailAuthorizationGuard",detail,"directoryAccessPermissionService",directories,"applicationHistoryGuard",history,"applicationEvidenceMapper",sqlMapper(DccControlledFileApplicationEvidenceMapper.class),"relationStageSnapshotService",ReflectionTestUtils.getField(signoff,"relationStageService"));
